CREATE FUNCTION public.list_clinic_users() RETURNS TABLE(id uuid,name text,email text,role public.app_role,active boolean,doctor_id uuid) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Acesso negado'; END IF; RETURN QUERY SELECT i.id,i.name,i.email,i.role,i.active,i.doctor_id FROM public.staff_invitations i ORDER BY i.name; END; $$;
CREATE FUNCTION public.manage_clinic_user(p_id uuid,p_name text,p_email text,p_role public.app_role,p_active boolean,p_doctor_id uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_email text; v_profile public.profiles; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Acesso negado'; END IF; PERFORM pg_advisory_xact_lock(735915); IF length(trim(p_name))<1 OR length(p_name)>150 OR p_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'Nome ou e-mail inválido'; END IF; IF p_role='doctor' AND (p_doctor_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.doctors WHERE id=p_doctor_id)) THEN RAISE EXCEPTION 'Vincule o cadastro do médico'; END IF; IF p_id IS NOT NULL THEN SELECT email INTO v_email FROM public.staff_invitations WHERE id=p_id; IF v_email IS NULL THEN RAISE EXCEPTION 'Usuário não encontrado'; END IF; IF lower(trim(p_email))<>v_email THEN RAISE EXCEPTION 'O e-mail de acesso não pode ser alterado'; END IF; ELSE v_email:=lower(trim(p_email)); END IF; SELECT * INTO v_profile FROM public.profiles WHERE lower(email)=v_email; IF v_profile.id=auth.uid() AND (NOT p_active OR p_role<>'admin') THEN RAISE EXCEPTION 'Você não pode remover seu próprio acesso administrativo'; END IF; INSERT INTO public.staff_invitations(id,email,name,role,active,doctor_id) VALUES(coalesce(p_id,gen_random_uuid()),v_email,trim(p_name),p_role,p_active,CASE WHEN p_role='doctor' THEN p_doctor_id END) ON CONFLICT(id) DO UPDATE SET name=excluded.name,role=excluded.role,active=excluded.active,doctor_id=excluded.doctor_id; IF v_profile.id IS NOT NULL THEN UPDATE public.profiles SET name=trim(p_name),active=p_active AND EXISTS(SELECT 1 FROM auth.users WHERE id=v_profile.id AND email_confirmed_at IS NOT NULL),doctor_id=CASE WHEN p_role='doctor' THEN p_doctor_id END WHERE id=v_profile.id; INSERT INTO public.user_roles(user_id,role) VALUES(v_profile.id,p_role) ON CONFLICT(user_id) DO UPDATE SET role=excluded.role; END IF; END; $$;
REVOKE EXECUTE ON FUNCTION public.list_clinic_users(),public.manage_clinic_user(uuid,text,text,public.app_role,boolean,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.list_clinic_users(),public.manage_clinic_user(uuid,text,text,public.app_role,boolean,uuid) TO authenticated;
DROP POLICY clinic_system_users_all ON public.system_users;
ALTER PUBLICATION supabase_realtime ADD TABLE public.staff_invitations;